	EVENT_INFO_CLICK_HINT = "Clique para traçar uma rota.",
	EVENT_INFO_STORMARION_DESC = "Defesa de torre em Voidstorm na Stormarion Citadel — começa a cada 30 minutos. Segure as ondas junto com todos na zona.",
	EVENT_INFO_STORMARION_REWARD = "Por run: Stormarion Core, Voidlight Marl, ouro e equipamento veterano. O baú semanal 'Stand Your Ground' tem chance de dar a montaria Contained Stormarion Defender e um mascote, além de renome com a The Singularity.",
	EVENT_INFO_HARANIR_DESC = "Um evento de história mais calmo em Harandar. Pegue a missão semanal 'Lost Legends', escolha uma relíquia e jogue sua linha de missões (dá para fazer solo).",
	EVENT_INFO_HARANIR_REWARD = "Um baú semanal, reputação Hara'ti e um item de decoração ligado à sua relíquia. Junte todas as histórias de relíquias para o título 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "semanal feita",
	EVENT_WEEKLY_TURNIN = "semanal: entregar!",
	EVENT_WEEKLY_ACTIVE = "semanal: em andamento",
	EVENT_WEEKLY_TODO = "semanal disponível",
	EVENT_WEEKLY_LABEL = "Semanal:",
	MODEL_PREVIEW_HINT = "Arraste para girar · role para dar zoom",
	MODEL_PREVIEW_SPIN = "Girar",
	MODEL_PREVIEW_RESET = "Redefinir",
	MODEL_PREVIEW_REWARDS_HINT = "Shift+clique: ver recompensas",
	WORLD_SUBTITLE = "Conteúdo de mundo semanal de Midnight em Quel'Thalas. Um Local ritual fica ativo em uma zona e o Vazio assalta outra — ambos compartilham o centro do Bazar, os Reconhecimentos de Campo e o renome.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals reúne os dois sistemas de mundo rotativos de Midnight. Locais rituais: interrompa o local ativo (ícone roxo) no seu obelisco. Assaltos do Vazio: limpe Golpes do Vazio na zona ativa para ativar uma Incursão do Vazio. Ambos dão Reconhecimentos de Campo, preenchem sua linha de mundo do Grande Cofre e alimentam o renome comum de Locais rituais. Ambas as semanais são pegas no centro do Bazar em Luenargente.",
	TAB_REFERENCE = "Básico",
	REF_PANEL_INTRO = "Explicações simples sobre sistemas de endgame. Mais tópicos aparecerão aqui com o tempo.",
	INFO_DRAWER_BODY_REFERENCE = "Guias para iniciantes: Crests, onde gastar e bônus de bando. Mais tópicos (profissões, etc.) virão depois.",
	TAB_SMC = "Silvermoon City",
	TAB_PROFESSIONS = "Profissões",
