	TAB_ACADEMY = "Academia de papéis",
	TAB_TOOLBOX = "Ferramentas",
	-- Artigos do códice do patch 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal e Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Um portal no Voidstorm (Screaming Ridge) leva a um de dois mundos do Vazio em rotação: o fúngico Naigtal ou o gélido Val. Ambos oferecem missões de mundo, raros, eventos de zona e um chefe mundial (Nexus-Captain Leth'ir / Imperator Pertinax). A semanal de Showdown concede um Riftstalker's Cache e conta para a fileira World do Grande Cofre. A Heroic World Tier opcional aumenta dificuldade e recompensas — escolha no portal. Comece com Riftblade Maella em Luaprata.",
	CODEX_127_SPOREFALL_TITLE = "Raide Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Raide de chefe único em Harandar: Rotmire, um gigante fúngico. Mesmo tier da Temporada 1 com itens de nível mais alto (LFR 259 / Normal 272 / Heroico 285 / Mítico 298); o Mítico é flexível com 15-25 jogadores. Pegue um Delicious Sporesnack uma vez por semana em qualquer dificuldade — quatro no total compram a montaria Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio e Runas (12.0.7)",
	CODEX_127_FOLIO_BODY = "Novo sistema de poder que não ocupa espaço de equipamento. Desbloqueie pela linha de missões do Sunstrider Omnium com Umbric e Rommath em Quel'Danas. A cada semana, a missão 'Seeking Knowledge' concede um Mote of Omnial Inquiry para abrir uma das cinco fileiras de runas; as runas trocam livremente fora de combate.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 jun - 11 ago)",
	CODEX_127_TIMEWAYS_BODY = "Maratona de Caminhada Temporal com seis masmorras de Dragonflight. Faça quatro masmorras numa semana para o buff Mastery daquela semana; consiga Mastery em quatro semanas distintas para a montaria Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Renome dos Locais Rituais (12.0.7)",
	CODEX_127_RITUALRENOWN_BODY = "Os Locais Rituais têm uma trilha de Renome por conta (8 níveis) na janela Journeys. Subir de nível enriquece cada local: Regeneration Orbs que curam, depois inimigos raros (nível 4), santuários de bônus (nível 5), tesouros maiores (nível 7) e elites raros (nível 8) — todos com espólios extra. Também desbloqueia itens de vendedores em Lua Prateada: decoração de lar do Vazio (nível 3, Rae'ana), mascotes (nível 6, Sergeant Vornin) e a montaria Void-Touched Hawkstrider (nível 8, Sergeant Vornin). Cada recompensa é de bando de guerra (Warband), então o teu progresso conta para a conta toda. Clique nos Loa Shrines brilhantes dentro de um site para um buff de atributo de 60 minutos (ex.: +10% de acerto crítico).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "Em desenvolvimento",
	TAB_BETA_TOOLTIP_BODY = "Esta guia está em beta inicial — o conteúdo está incompleto, pode mudar com frequência e ainda não está pronto para uso completo.",
	TAB_ADDONS = "Complementos",
	SEARCH_CHAT_TAB_ACADEMY = "Guia aberta: Academia de Funções",
	ACADEMY_SUBTITLE = "Masterclass curta para tankar e curar em grupos - mentalidade, caixas de seleção de preparação e uma rampa suave para as masmorras. Não é um guia de análise.",
	ACADEMY_TRACK_TANK = "Trilha do tanque",
	ACADEMY_TRACK_HEAL = "Trilha de cura",
	ACADEMY_CLASS_FMT = "Conectado: %s - %s (abra Macros / Consumíveis / Guias na barra lateral)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros abertas para %s - %s. Verifique também os consumíveis para frascos e potes.",
	ACADEMY_PREF_TITLE = "Lista de verificação pré-voo (marque quando estiver pronto)",
	ACADEMY_PREF_HINT = "Os ticks são salvos em suas configurações. Abra a guia correspondente na barra lateral durante a preparação.",
	ACADEMY_PREF_TANK_INTERRUPT = "Interromper macro na minha barra (guia Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Uma defesa pronta (Guias -> aba Defensivas ou Em grupos)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Frasco/pote pronto (guia Consumíveis)",
	ACADEMY_PREF_TANK_TAUNT = "Eu conheço minha chave de provocação (teste fictício uma vez)",
	ACADEMY_PREF_HEAL_MACROS = "Macros de recuperação de mouse/foco (guia Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Defensivo pessoal na barra (Guias -> Defensivos ou Em grupos)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pote/frasco de mana (guia Consumíveis)",
	ACADEMY_PREF_HEAL_PRACTICE = "Pratiquei cura flutuante em um amigo uma vez",
	ACADEMY_TANK_INTRO_TITLE = "Mentalidade de tanque",
	ACADEMY_TANK_INTRO_BODY = "Seu trabalho é definir o ritmo e manter a atenção, e não aumentar os medidores de dano.\n\nUm puxão constante supera uma rotação perfeita em um grupo morto. Diga puxa em voz alta se ajudar: \"puxando 3\".",
	ACADEMY_TANK_PULL_TITLE = "Durante uma puxada (primeiros 10 segundos)",
	ACADEMY_TANK_PULL_BODY = "1. Pegue o pacote (provocação/ameaça).\n2. Enfrente os inimigos longe do grupo quando puder.\n3. Use uma defensiva se o dano aumentar - guarde a segunda para \"ah, não\".\n4. Interrompa o lançamento que causa mais dano (geralmente cura ou grande golpe).\n\nVocê não precisa de todas as habilidades no tempo de recarga imediatamente.",
	ACADEMY_TANK_WIPE_TITLE = "Quando dá errado",
	ACADEMY_TANK_WIPE_BODY = "Uma limpeza são dados, não um veredicto. Pergunte: \"Eu estava muito à frente?\" ou \"Eu salvei uma defensiva?\"\n\nRepare, coma, tente novamente.",
	ACADEMY_TANK_DUNGEON_TITLE = "Sua primeira masmorra (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Comece normalmente com amigos ou guildas, se puder. Vá devagar nos puxões - dois pacotes pequenos vencem uma corrente enorme.\n\nObserve a mana do curador; faça uma pausa entre puxadas. Não há problema em pedir CC ou \"nenhuma grande atração ainda\".",
	ACADEMY_TANK_RAID_TITLE = "Raids e LFR (mais tarde)",
	ACADEMY_TANK_RAID_BODY = "LFR é a introdução suave do ataque: perdoando, muitos curandeiros. Concentre-se nos horários das provocações dos chefes e fique parado no lugar certo.\n\nTanques de ataque míticos não são o próximo passo: conforto em heróico/LFR primeiro.",
	ACADEMY_TANK_CHAT_TITLE = "Bate-papo de festa",
	ACADEMY_CHAT_HINT = "Clique em uma linha ou no ícone de cópia e depois em Ctrl+C para colar no chat do grupo.",
	ACADEMY_CHAT_COPY_TIP = "Selecione esta linha (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Ainda aprendendo tanque - vá devagar, por favor.\"\n\"Puxando 3...\"\n\"Preciso de um descanso para mana.\"\n\"Interrompa em [nome do feitiço] - eu tenho o próximo.\"\n\"Mais uma tentativa - eu conheço esse puxão agora.\"",
	ACADEMY_TANK_LADDER_TITLE = "Escada de ansiedade (ordem recomendada)",
	ACADEMY_TANK_LADDER_BODY = "1. Elites mundiais abertas com um amigo\n2. Delves (instância menor - guia Delves)\n3. Masmorra normal com pessoas em quem você confia\n4. Heroico / LFR quando confortável\n\nPule uma etapa até que pareça chato, não assustador.",
	ACADEMY_TANK_BOTH_TITLE = "Aprender a curar também?",
	ACADEMY_TANK_BOTH_BODY = "Ótimo - mas escolha um papel principal nas masmorras por um tempo. Pratique o outro em mergulhos ou mundo aberto.\n\nTrocar tanque e curar no mesmo pug M+ dobra o estresse; o domínio em uma função primeiro cria confiança para a segunda.",
	ACADEMY_HEAL_INTRO_TITLE = "Curar mentalidade",
	ACADEMY_HEAL_INTRO_BODY = "Você não é responsável por todos com 100% de saúde o tempo todo.\n\nSeu trabalho é fazer a triagem: manter o tanque vivo, salvar a pessoa prestes a morrer e depois o resto. Alguns danos são normais – a cura excessiva do pânico esvazia mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triagem (quem primeiro?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Você (se estiver morrendo - o curandeiro morto não cura ninguém)\n2. Tanque (se o pacote ainda estiver com eles)\n3. Qualquer pessoa com menos de 40% ou com uma penalidade mortal\n4. Todos os outros com cura eficiente\n\nGrande cura após grande dano; pequenas curas entre eventos.",
	ACADEMY_HEAL_WIPE_TITLE = "Quando dá errado",
	ACADEMY_HEAL_WIPE_BODY = "\"Eu poderia ter salvado o tanque?\" é a pergunta útil - não \"por que o DPS ficou em chamas?\"\n\nSe a mana estava vazia, use feitiços mais eficientes na próxima vez. Uma limpeza não significa que você não possa curar.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Sua primeira masmorra (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Diga ao grupo que você está aprendendo. Fique ao alcance do tanque; deixe o DPS dar um arranhão antes de explodir mana.\n\nEntre os puxões: beba, buff, respire. Você tem permissão para dizer “oom, 5 seg”.",
	ACADEMY_HEAL_RAID_TITLE = "Raids e LFR (mais tarde)",
	ACADEMY_HEAL_RAID_BODY = "LFR: o dano em todo o raid é previsível após uma limpeza. Aprenda o cronômetro de luta, não as barras de cada jogador.\n\nAs curas de raid usam a mesma triagem: tanques e janelas de recarga de raid primeiro.",
	ACADEMY_HEAL_CHAT_TITLE = "Bate-papo de festa",
	ACADEMY_HEAL_CHAT_BODY = "\"Aprendendo curandeiro - vou chamar mana baixa.\"\n\"Tanque é prioridade - grite se precisar respirar.\"\n\"Grande cura para você - cuidado com sua saúde.\"\n\"Espere 5 segundos entre puxadas.\"\n\"Isso foi por minha conta - vou guardar mais para o tanque na próxima puxada.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Escada de ansiedade (ordem recomendada)",
	ACADEMY_HEAL_LADDER_BODY = "1. Cure um amigo no mundo aberto\n2. Investiga com um pequeno grupo\n3. Masmorra normal com amigos pacientes\n4. Raid LFR / heroico quando pronto\n\nDelves são o passo mais fácil para o conteúdo instanciado.",
	ACADEMY_HEAL_BOTH_TITLE = "Tanque de aprendizagem também?",
	ACADEMY_HEAL_BOTH_BODY = "Use a trilha Tank para entrar na fila das masmorras; continue curando nas investigações até que tankar pareça familiar.\n\nDuas funções em uma semana em pugs é muito - uma função como \"principal\" reduz o medo.",
	INFO_DRAWER_BODY_ACADEMY = "Role Academy: trilhas de tanque/cura, caixas de seleção pré-voo, notas de masmorras vs ataques e linhas de bate-papo do grupo. Guias de nivelamento adicionam uma guia de consultor em grupos por função. Use a barra lateral para macros, consumíveis, guias e análises.",
	TAB_GUIDE_SUB_GUIDE = "Guia",
	TAB_GUIDE_SUB_LAYOUT = "Disposição",
	TAB_LEVELING_SUB_LAYOUT = "Disposição",
	MACROS_TYPE_INTERRUPT = "Interromper",
	MACROS_TYPE_UTILITY = "Utilitário",
	MACROS_CONSUMABLES_SUBTITLE = "Melhores escolhas da 1ª temporada da meia-noite (frasco, potes, banquete, comida). Passe o mouse sobre uma linha para ver a dica de ferramenta do item.",
	MACROS_CONS_NO_DATA = "Ainda não há dados de consumíveis para esta classe e especificação.",
