	PROFHUB_GOAL_LABEL = "Meta do conselho:",
	PROFHUB_GOAL_ALLROUND = "Versátil",
	PROFHUB_GOAL_GOLD = "Ouro",
	PROFHUB_GOAL_SELF = "Autossuficiente",
	PROFHUB_GOAL_TT_ALLROUND = "A rota inicial de consenso: uma ordem equilibrada para seus primeiros pontos — boa capacidade de fabricação sem se prender a um nicho.",
	PROFHUB_GOAL_TT_GOLD = "Prioriza árvores cujos produtos vendem bem (encantamentos, frascos, cooldowns de rolos, gemas lapidadas). Escolha isto se ouro é a sua meta.",
	PROFHUB_GOAL_TT_SELF = "Prioriza fabricar seus próprios consumíveis e equipamentos, e a autossuficiência de materiais, acima do valor de mercado.",
	PROFHUB_WEEKLY_TRAINER_REQ_ENCH = "(desbloqueia com a intro do capitão Flaresworn — estação de encomendas; também exige perícia 25)",
	PROFHUB_ACCESSORY_HINT_FMT = "Dica: %d slot(s) de acessório vazio(s) — acessórios dão perícia e stats. Outros artesãos os fabricam (leilão: Equipamento de profissão).",
	INFO_DRAWER_BODY_CONSUMABLES = "Consumíveis da 1ª temporada da meia-noite por especificação (lista Wowhead). Use Meu personagem, < >, ou pesquise (por exemplo, estragos, besta) para visualizar outra especificação sem relogar.",
	MACROS_MACRO_NAME_FMT = "%s",
	MACROS_COPY_SUFFIX = "Copie o texto abaixo em Esc > Macros > Novo. Em seguida, arraste o ícone da macro para um local na barra de ação (por exemplo, 1, 2 ou E).",
	MACROS_INTERRUPT_SUBTITLE = "Dica da meia-noite: interrompe uma conjuração inimiga com um toque. Escolha uma variante acima (Foco ou Mouseover), leia a nota e copie o texto abaixo.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Foco",
	MACROS_INTERRUPT_VARIANT_MOUSEOVER = "Mouseover",
	MACROS_INTERRUPT_DESC_FOCUS = "Interrompe seu foco se for um inimigo vivo; caso contrário, seu alvo atual. Defina o conjurador perigoso como foco uma vez (/focus) e continue atacando seu próprio alvo — esta macro nunca altera nem limpa seu foco.",
	MACROS_INTERRUPT_DESC_MOUSEOVER = "Interrompe o inimigo sob o cursor do mouse (também funciona nas placas de nome e molduras); caso contrário, seu alvo atual. Sem foco: aponte para o conjurador e pressione.",
	MACROS_UTILITY_SUBTITLE = "Dica da meia-noite: macros úteis para suas especificações (cursor, mouseover, foco). Escolha um acima, leia a nota e copie o texto abaixo.",
	MACROS_ERR_NO_UTILITY = "Nenhuma macro utilitária listada para esta especificação ainda.",
