	KEYBIND_ROLE_COOLDOWN = "Barra de resfriamento",
	LAYOUT_PROTOTYPE_SUBTITLE = "Protótipo – visualização completa do teclado dos EUA: as teclas da meia-noite acendem; outros ficaram acinzentados. Passe o mouse ou clique. As dicas na guia Guia podem pular aqui e destacar uma chave. É seguro remover quando substituído.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888Não usado no mapa de ligação Midnight Hunter.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Tecla modificadora – WoW lida com combos Shift/Ctrl/Alt separadamente deste mapa de feitiços.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Cluster de navegação/edição — não faz parte do mapa de teclas Midnight.|r",
	LAYOUT_KEY_EMPTY_TOOLTIP = "|cffaaaaaaAinda não há função nesta chave no mapa de especificações atual.|r",
	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaSlot G existe na grade, mas esta equipe geralmente o deixa vazio — opcional bind.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Mova seu personagem: W para frente, S para trás, A/D strafe, mouse para virar. WoW os usa por padrão – mantenha-os livres para caminhar.",
	LAYOUT_KEY_TAB_TOOLTIP = "A guia alterna os alvos. WoW usa-o por padrão – mantenha Tab livre para que você possa escolher o inimigo certo rapidamente em combate.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Dica da meia-noite: mantenha esta tecla livre para feitiços, macros ou combos Shift/Ctrl/Alt – a mesma ideia das teclas F acesas em suas barras de ação.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = mover (W A S D).\n|cffe0e070Gold|r = feitiços e atalhos neste mapa.\n|cff59d9ffTab|r = trocar de alvo rapidamente.\n|cff888888Grey|r = não neste mapa inicial.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Aberto no seu guia de nivelamento – esta chave está no mapa Midnight.|r",
	MODULE_PLACEHOLDER = "Espaço reservado para módulo — o conteúdo de \"%s\" será montado aqui.",
	INFO_DRAWER_TOGGLE_SHOW = "Informações",
	INFO_DRAWER_TOGGLE_HIDE = "Fechar",
	INFO_DRAWER_TITLE_FMT = "%s - Como usar",
	INFO_DRAWER_BODY_DELVES = "Centro de comando Midnight Delves para seu personagem atual.\n\nExpanda Great Vault para rastreamento de recompensas semanais ou Midnight Delves para moedas da temporada (Restored Coffer Keys, Shards semanais, Undercoins), Delver's Journey / renome e a lista completa de Delve com detecção abundante ao vivo de POIs do mapa.\n\nNavegação: clique com o botão direito em uma linha para direcionar para a entrada. |cffffcc00TomTom (recomendado)|r adiciona a seta do mapa e a fila do waypoint. |cff00ff00Travel Assistant|r (pop-up quando você está longe) mostra os atalhos do Hearthstone e do portal central e funciona |cffffff00sem|r TomTom.\n\nO Find Nearest Bountiful requer a instalação do TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Lista de vários personagens armazenada localmente por este complemento (variáveis salvas no seu PC, não na sincronização com a nuvem da Blizzard).\n\nCada linha lista Chaves, Fragmentos, Undercoins, eco de profissões e um resumo compacto do Great Vault com dicas de ferramentas ricas; seu personagem logado é destacado e a classificação favorece a utilidade.\n\nAs linhas são atualizadas no login e na moeda/eventos semanais. Excluir remove apenas dados de instantâneos adicionais – nunca seu personagem WoW real.",
	INFO_DRAWER_BODY_RARES = "Raros do mundo Midnight por zona (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nEscolha uma zona à esquerda. Verde = feito neste personagem; UP verde = vignette no spawn (provavelmente ativo); traço cinza = não no mapa agora.\n\nRare mais próximo = um pin; Gerar rota = todos os raros abertos no TomTom. Status UP é aproximado — abra o mapa da zona ou aproxime-se se tiver dúvida.",
	RARES_TITLE = "Raros Midnight",
	RARES_SUBTITLE_FMT = "%d/%d feitos · %d visíveis no mapa (estrela prateada)",
	RARES_EMPTY_ZONE = "Nenhuma lista de raros para esta zona.",
	RARES_BTN_NEAREST = "Rare mais próximo",
	RARES_BTN_ROUTE = "Gerar rota",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: rare mais próximo — %s",
	RARES_NEAREST_NONE = "Nenhum rare incompleto restante nesta zona.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant indisponível (módulo Profundidades não carregado).",
	RARES_ROUTE_DONE_FMT = "%d/%d raros incompletos no TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Ordem: o mais próximo primeiro, depois o seguinte a cada passo.",
	RARES_ROUTE_ORDER_LIST = "Ordem: ordem da lista (posição indisponível).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Feito esta semana neste personagem (reset na quarta).",
	RARES_TIP_UP = "Provavelmente ativo (vignette do mapa no spawn).",
	RARES_TIP_DOWN = "Não no mapa agora — pode spawnar depois.",
	RARES_TIP_VIGNETTE_NOTE = "Status do mapa é aproximado; abra o mapa da zona ou aproxime-se se não tiver certeza.",
	INFO_DRAWER_BODY_SMC = "Referência de Silvermoon City para Midnight (mapa 2393). A mesma rolagem começa com a lista de verificação semanal/hub quando os IDs de missão são configurados e depois continua em grades de pinos categorizadas: Serviços essenciais, viagens, centros de missões, treinadores profissionais, reuniões e muito mais.\n\nCada botão de localização define o waypoint do usuário da Blizzard e, com o TomTom instalado, espelha-o através da barra auxiliar (/way #2393 …).\n\nO progresso da lista de verificação tinge os botões de waypoint relacionados em verde; atualize os IDs das missões nos dados após patches importantes se uma linha parecer errada.",
	INFO_DRAWER_BODY_PROFESSIONS = "Rastreia os Pontos de Conhecimento (KP) da profissão Midnight para seu personagem atual, além de linhas monetárias quando o cliente os expõe (Abundância Unalloyed, Moxie do Artesão, Fragmentos de Dundun semanais).\n\nAbaixo disso, duas colunas listam missões de Coleta de Conhecimento e livros de profissão por troca – os ícones mostram se cada missão foi concluída. Clique em uma linha para enviar apenas esse alfinete para a TomTom (limpa outros pontos de referência; o Travel Assistant lida com saltos entre zonas quando o TomTom é carregado).\n\nBotões inferiores colocam alfinetes incompletos na fila em lote: Gerar tesouros ou Gerar livros (o mais próximo inacabado primeiro quando sua posição no mapa estiver disponível).",
	INFO_DRAWER_BODY_GUIDE = "Referências de nivelamento especificação por especificação inspiradas em Icy Veins: prioridade de estatísticas, escolhas de equipamentos, consumíveis filtrados de acordo com o que seu nível pode realmente usar, linhas de dicas de feitiços opcionais e o Leveling Advisor com guias de colchetes para rotação, defesas e foco em talentos.\n\nQuando sua classe tem um mapa de teclas Midnight (Hunter / Paladin por enquanto), as dicas podem mostrar um botão de chave dourada - clique nele para abrir a guia Layout e destacar essa tecla no teclado. Isso vincula a leitura (o que pressionar) ao posicionamento (onde no teclado), para que você aprenda fazendo.\n\nA barra de pesquisa global entende palavras-chave do guia e pode alternar entre as guias do Midnight Helper; A visualização permite que você leia outra especialização sem se registrar novamente enquanto Meu personagem volta à sua especificação ativa.\n\nA visibilidade da guia Guia segue as configurações: Automático (oculta no nível 90+), Sempre mostrar ou Sempre ocultar.",
	INFO_DRAWER_BODY_MACROS = "Guia de interrupção: macro de chute de equipe (foco primeiro). Guia Utilitário: macros de especificações extras (feitiços de cursor terrestre, curas de mouseover e similares) do pacote de equipe. Escolha uma linha, leia a dica, copie o texto.\n\nOs dados podem mudar após os patches. Informe os feitiços perdidos à equipe.",
	INFO_DRAWER_BODY_ADDONS = "Central para ferramentas opcionais incluídas no Midnight Helper, em vez de downloads separados.\n\nEscolha uma subguia na parte superior, que hoje é Platynator: link do Wago, importação de string de perfil e galeria visual do MF Platynator.\n\nPainéis de parceiros adicionais são registrados aqui automaticamente quando módulos futuros forem enviados.",
	ABOUT_WINDOW_TITLE = "Sobre Ajudante da Meia-Noite",
	ABOUT_VERSION_FMT = "Versão instalada: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Autores: TwelveInchy & Claude\n\nO teu companheiro Midnight tudo-em-um, organizado em quatro salas — Me, Codex, Tools e Settings. Fixa favoritos sob a barra de pesquisa e escreve para saltar para qualquer lado. Inclui Esta semana, Delves & Vault, coaches de Delve e Ritual, o assistente de Encantamentos e Gemas, instantâneo da conta, guias do Codex, profissões e ferramentas integradas — EN / NL / DE / FR / ES / PT / IT.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Versão: %s",
	CHANGELOG_TITLE = "Log de alterações do ajudante da meia-noite",
	CHANGELOG_SUBTITLE = "Versão %s",
	CHANGELOG_VERSION_FMT = "Versão %s",
	CHANGELOG_CLOSE = "Fechar",
	CHANGELOG_CB_UNTIL_NEXT = "Não mostrar novamente até a próxima versão",
	CHANGELOG_CB_NEVER = "Ocultar permanentemente o changelog",
	CHANGELOG_120_1 = "Adicionado painel compacto do Leveling Advisor com colchetes e guias por nível (Rotação / Defensivos / Foco em talentos).",
	CHANGELOG_120_2 = "Seção de consumíveis aprimorada: mostra apenas itens utilizáveis no seu nível atual e explica os próximos desbloqueios.",
	CHANGELOG_120_3 = "Adicionado gerenciamento de linha de instantâneo da conta: exclua caracteres obsoletos com segurança (com confirmação) além de listras de zebra.",
	CHANGELOG_120_4 = "Melhor consistência de localização (EN/NL) e glossário de estatísticas adicionado no guia por meio do novo ? Botão de estatísticas.",
	CHANGELOG_121_1 = "Janela principal: os painéis internos respeitam a moldura de diálogo dourada – os ornamentos dos cantos permanecem visíveis e a “caneta vazia” inferior/direita ao lado da alça de redimensionamento desaparece.",
	CHANGELOG_121_2 = "Informações e Sobre usam os botões padrão do painel da Blizzard novamente (mesmo tratamento de Pesquisar/Meu personagem) para uma aparência consistente em todos os clientes.",
	CHANGELOG_121_3 = "Somente polimento menor; Profundidades, Vault, guias e comportamento de localização inalterados – atualização segura.",
	CHANGELOG_122_1 = "Guia Macros: macro de interrupção de equipe com um clique, além de macros utilitárias selecionadas por especificação (cursor, mouseover, foco) — copiar, colar, reproduzir.",
	CHANGELOG_122_2 = "Visualize qualquer especificação sem registrar novamente: guie a pesquisa, atualize dicas de nivelamento, layout de teclado e macros para essa classe/especificação de uma só vez.",
	CHANGELOG_122_3 = "As mensagens de pesquisa e bate-papo do guia seguem sua escolha de idioma (/mh lang en ou nl).",
	CHANGELOG_122_4 = "Atualização do layout das teclas à meia-noite: interrupção em E, slots de função mais claros, overflow mais inteligente (Alt, Shift, Ctrl).",
	CHANGELOG_122_5 = "Ainda cozinhando: tudo no Midnight Helper está sujeito a mudanças e melhorias constantes – os patches continuarão chegando. Feedback bem-vindo!",
	CHANGELOG_130_1 = "Compartilhar dicas em grupo: envie dicas de delve para party, raid ou chat de instância do Treinador de profundidades (breve, chefe, seções, cópia). Teste (/diga) quando estiver sozinho.",
	CHANGELOG_130_2 = "Pop-up de itens de Delve: RAID-R Mini e Trovehunter's Bounty em Delves - painel automático + ícones de minimapa (somente em Delve; esquerda = pop-up, direita = usar).",
	CHANGELOG_130_3 = "Treinador de profundidades: Shift + roda do mouse dimensiona todo o painel (como Midnight Helper). Arraste o canto, a borda inferior ou a borda direita para redimensionar; dicas de rolagem da roda.",
	CHANGELOG_130_4 = "Destaque do chefe: visualização confiável do primeiro carregamento, correção de texto de carregamento e zoom salvo por chefe.",
	CHANGELOG_130_5 = "Correções: compartilhamento de grupo somente quando você estiver realmente agrupado; menos erros de chat; soletrar links em dicas compartilhadas (EN/NL).",
	CHANGELOG_130_6 = "A partir daqui, pequenos lançamentos de patch podem usar o codinome Valeera nas notas – os principais recursos permanecem em 1.x.",
	CHANGELOG_126_1 = "Treinador de profundidades: dicas flutuantes para todos os 11 mergulhos da meia-noite (visão geral, rota, lixo, chefe) em inglês e holandês.",
	CHANGELOG_126_2 = "Destaque Boss com visualização 3D; role no modelo para aumentar/diminuir o zoom (salvo por chefe).",
	CHANGELOG_126_3 = "Links de feitiço azul nas dicas; visualização na guia Delves ou /mh coach; exibição automática em Delve.",
	CHANGELOG_126_4 = "Janela de coach arrastável e redimensionável com minimização.",
	CHANGELOG_126_5 = "Câmera Boss e correções de dicas para varejo.",
	CHANGELOG_125_1 = "Nova guia Role Academy: trilhas de tanque e cura com listas de verificação de preparação, dicas de triagem e uma rampa suave de mergulhos até masmorras.",
	CHANGELOG_125_2 = "Links rápidos da Role Academy para Macros, Consumíveis, Guias de Nivelamento e Delves.",
	CHANGELOG_125_3 = "Pesquise palavras-chave (tanque, cura, academia, mentor) para abrir a Role Academy.",
	CHANGELOG_124_1 = "Roteamento aprofundado e profissional: substituto do waypoint do mapa da Blizzard quando o TomTom não está instalado (SuperTrack + pop-up de viagem inalterado).",
	CHANGELOG_124_2 = "Instantâneo da conta: moedas semanais da profissão na dica de ferramenta (Abundância, fragmentos de Dundun, resumo de Moxie).",
	CHANGELOG_124_3 = "Grandes lembretes de redefinição do Vault: bate-papo no login, linhas de dicas de ferramentas do minimapa e ícone pulsante do minimapa (configurável).",
	CHANGELOG_124_4 = "Atualização do instantâneo da conta: classificação/filtro, nível/ilvl, emblema obsoleto, Cristais de Mana Imaculados; roteamento de busca de consumíveis.",
	CHANGELOG_123_1 = "Corrigido o Travel Assistant que sugeria erroneamente Hearthstone quando você já estava perto de uma caverna ou dentro de uma.",
	CHANGELOG_123_2 = "Corrigido um erro Lua ao rotear para delves abundantes (API de posição do mapa).",
	CHANGELOG_123_3 = "Guia da barra lateral de consumíveis: listas baseadas no Wowhead por especificação, com visualização de pesquisa guia.",
	CHANGELOG_123_4 = "Orientação TomTom mais clara (EN/NL): opcional para setas do mapa; O Travel Assistant funciona sem o TomTom.",
